```sql
SELECT DISTINCT LName, Fname
FROM Student
WHERE Major IN (
    SELECT StuID FROM Plays_Games WHERE GameID IN (
        SELECT GameID FROM Video_Games WHERE GName LIKE '%Football%' OR GName LIKE '%Lacrosse%'
    )
)
ORDER BY Fname;
```

```sql
