```

```sql
SELECT CAST(SUM(DIVIDE(W, G)) AS REAL) / COUNT(oppID) as winning_rate FROM TeamsHalf t JOIN Teams h ON t.year = h.year AND t.tmID = h.tmID WHERE t.year = 2000;
```

```sql
SELECT AVG(DIVIDE(W, G)) AS average_winning_rate FROM Teams WHERE year = 2000 AND tmID = 'MTL';
```
